    function setActiveNav() {
        const currentPath = window.location.pathname.split('/').pop() || 'index.html';
        const navLinks = document.querySelectorAll('.primary-nav a');

        navLinks.forEach(link => {
            const href = link.getAttribute('href');
            if (href === currentPath || (currentPath === '' && href === 'index.html')) {
                link.setAttribute('aria-current', 'page');
            } else {
                link.removeAttribute('aria-current');
            }
        });
    }

    // --- Filtering Logic ---
    function initFilters() {
        const projectFilters = document.querySelectorAll('[data-filter-group="projects"]');
        const blogFilters = document.querySelectorAll('[data-filter-group="blog"]');

        if (projectFilters.length > 0) {
            projectFilters.forEach(filter => {
                filter.addEventListener('click', (e) => {
                    if (e.target.tagName !== 'BUTTON') return;
                    const category = e.target.dataset.category;
                    renderProjects(category);
                    // Update active state on filter buttons
                    projectFilters.forEach(btn => btn.classList.remove('active'));
                    e.target.classList.add('active');
                });
            });
            // Initial render
            renderProjects('all');
        }

        if (blogFilters.length > 0) {
            blogFilters.forEach(filter => {
                filter.addEventListener('change', (e) => {
                    const year = e.target.value;
                    renderBlogPosts(year);
                });
            });
            // Initial render
            renderBlogPosts('all');
        }
    }

    function renderProjects(category) {
        const grid = document.getElementById('projects-grid');
        if (!grid) return;

        const filtered = category === 'all' 
            ? projects 
            : projects.filter(p => p.category === category);

        grid.innerHTML = filtered.map(project => `
            <li class="card">
                <h3 class="card-title"><a href="${project.url}">${project.title}</a></h3>
                <p class="card-meta">${project.category}</p>
                <p>${project.description}</p>
            </li>
        `).join('');
    }

    function renderBlogPosts(year) {
        const list = document.getElementById('blog-list');
        if (!list) return;

        const filtered = year === 'all'
            ? blogPosts
            : blogPosts.filter(p => p.date.startsWith(year));

        list.innerHTML = filtered.map(post => `
            <article class="card">
                <h3 class="card-title"><a href="${post.url}">${post.title}</a></h3>
                <p class="card-meta">${new Date(post.date).toLocaleDateString()}</p>
                <p>${post.excerpt}</p>
            </article>
        `).join('');
    }

    // --- Contact Form Simulation ---
    function initContactForm() {
        const form = document.getElementById('contact-form');
        if (!form) return;

        form.addEventListener('submit', (e) => {
            e.preventDefault();
            const btn = form.querySelector('button[type="submit"]');
            const originalText = btn.textContent;

            btn.disabled = true;
            btn.textContent = 'Sending...';

            // Simulate network delay
            setTimeout(() => {
                btn.textContent = 'Message Sent!';
                btn.classList.add('btn-secondary');
                btn.classList.remove('btn');

                // Reset form after delay
                setTimeout(() => {
                    form.reset();
                    btn.disabled = false;
                    btn.textContent = originalText;
                    btn.classList.remove('btn-secondary');
                    btn.classList.add('btn');
                }, 3000);
            }, 1000);
        });
    }

    // --- Initialization ---
    document.addEventListener('DOMContentLoaded', () => {
        setActiveNav();
        initFilters();
        initContactForm();
    });

})();
